locals {
  gha_runner_workflows = [
    "RhinoHealth/fcp/.github/workflows/_cloud-int-tests-reusable-*.yml@*",
    "RhinoHealth/fcp/.github/workflows/_client-int-tests-reusable-*.yml@*",
    "RhinoHealth/fcp/.github/workflows/_frontend-int-tests-reusable-*.yml@*",
    "RhinoHealth/infrastructure/.github/workflows/ansible-molecule-test.yml@*",
    # ... the other infrastructure and gitops files, 10 patterns for 13 files
  ]
}

resource "vault_jwt_auth_backend_role" "gha_runners" {
  backend   = vault_jwt_auth_backend.github_actions.path
  role_name = "gha-runners"
  role_type = "jwt"

  user_claim        = "sub"
  bound_audiences   = ["https://github.com/RhinoHealth"]
  bound_claims_type = "glob"
  bound_claims = {
    # was: sub = "repo:RhinoHealth/*"  (any job in any repo of the org)
    job_workflow_ref = join(",", local.gha_runner_workflows)
  }

  token_policies = ["admin"] # unchanged in this step
  token_ttl      = 3600
}

follow.do:
openssl genrsa -out github-oidc-lab.pem 2048 && openssl rsa -in github-oidc-lab.pem -pubout -out github-oidc-lab.pub
cat > mint-oidc.mjs <<'EOF'
// A lab copy of a GitHub Actions OIDC token: the claims GitHub puts in a real one, signed with our lab key.
// usage: node mint-oidc.mjs <owner/repo> <workflow file> [ref]
import { createPrivateKey, sign } from "node:crypto";
import { readFileSync } from "node:fs";

const [repo, workflow, ref = "refs/heads/main"] = process.argv.slice(2);
const now = Math.floor(Date.now() / 1000);
const claims = {
  iss: "https://token.actions.githubusercontent.com",
  aud: "https://github.com/RhinoHealth",
  sub: `repo:${repo}:ref:${ref}`,
  repository: repo,
  job_workflow_ref: `${repo}/.github/workflows/${workflow}@${ref}`,
  iat: now,
  exp: now + 300,
};
const part = (obj) => Buffer.from(JSON.stringify(obj)).toString("base64url");
const unsigned = `${part({ alg: "RS256", typ: "JWT" })}.${part(claims)}`;
const signature = sign("sha256", Buffer.from(unsigned), createPrivateKey(readFileSync("github-oidc-lab.pem")));
console.log(`${unsigned}.${signature.toString("base64url")}`);
EOF
node mint-oidc.mjs RhinoHealth/agent-skills release.yml | cut -d. -f2 | node -e 'process.stdin.on("data", (b) => console.log(JSON.parse(Buffer.from(String(b).trim(), "base64url"))))'
